<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { PageHeader, RefreshButton } from './ui';
	import Icon from './Icon.svelte';
	import { uiText as t } from './i18n';
	type Provider={id:string;purpose:string;driver:string;name:string;endpoint:string;active:boolean;has_secret:boolean;version:number};
	let drivers=$state<{id:string;name:string}[]>([]);
	let providers=$state<Provider[]>([]),vaultReady=$state(false),loading=$state(true),busy=$state(false),error=$state(''),notice=$state('');
	let editing=$state(false),id=$state<string|null>(null),version=$state<number|null>(null),purpose=$state('biometric_enrollment'),driver=$state('signed_bridge_v1'),name=$state(''),endpoint=$state(''),secret=$state(''),active=$state(false),clearSecret=$state(false),hasSecret=$state(false);
	const label=(value:string)=>t(value==='biometric_enrollment'?'Biometrik wajah':'Tanda tangan dokumen');
	async function load(){loading=true;error='';try{const data=await request<{providers:Provider[];vault_ready:boolean;drivers:{id:string;name:string}[]}>('/v1/admin/integrations');providers=data.providers;drivers=data.drivers;vaultReady=data.vault_ready;}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}finally{loading=false;}}
	function edit(provider?:Provider){id=provider?.id??null;version=provider?.version??null;purpose=provider?.purpose??'biometric_enrollment';driver=provider?.driver??'signed_bridge_v1';name=provider?.name??'';endpoint=provider?.endpoint??'';active=provider?.active??false;hasSecret=provider?.has_secret??false;secret='';clearSecret=false;editing=true;notice='';}
	async function save(){busy=true;error='';notice='';try{await request('/v1/admin/integrations',{method:'POST',body:JSON.stringify({id,version,purpose,driver,name,endpoint,active,secret:secret||null,clear_secret:clearSecret})});secret='';editing=false;await load();notice=t('Konfigurasi integrasi tersimpan. Tantangan lama telah dibatalkan.');}catch(cause){secret='';error=cause instanceof Error?cause.message:t('Gagal menyimpan data.');}finally{busy=false;}}
	onMount(load);
</script>
<svelte:head><title>{t('Integrasi layanan')} · PasPapan</title></svelte:head>
<main class="workspace-page integrations" id="main-content" tabindex="-1">
	<PageHeader title={t('Integrasi layanan')} description={t('Ganti layanan per perusahaan. Satu provider aktif untuk setiap jenis verifikasi.')} backHref="/admin/dashboard">{#snippet actions()}<button onclick={()=>edit()}><Icon name="plus" size={15}/>{t('Tambah provider')}</button>{/snippet}</PageHeader>
	{#if error}<p role="alert">{error}<RefreshButton onclick={load} label={t('Coba lagi')}/></p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
	{#if !loading&&!vaultReady}<p class="panel" role="status">{t('Penyimpanan kredensial belum siap. Master key perlu dikonfigurasi di server satu kali.')}</p>{/if}
	{#if editing}<form novalidate class="panel editor editor-form" onsubmit={event=>{event.preventDefault();void save();}}><h2>{t(id?'Edit provider':'Provider baru')}</h2><label>{t('Jenis layanan')}<select bind:value={purpose} disabled={Boolean(id)}><option value="biometric_enrollment">{t('Biometrik wajah')}</option><option value="document_signature">{t('Tanda tangan dokumen')}</option></select></label><label>{t('Nama layanan')}<input bind:value={name} maxlength="100" required/></label><label>{t('Protokol integrasi')}<select bind:value={driver}>{#each drivers as adapter}<option value={adapter.id}>{adapter.id==='signed_bridge_v1'?t('Bridge verifikasi bertanda tangan'):adapter.name}</option>{/each}</select></label><label>{t('URL layanan')}<input type="url" bind:value={endpoint} placeholder="https://" maxlength="2000" required/></label><label>{t(hasSecret?'Kredensial pengganti (opsional)':'Kredensial layanan')}<input type="password" bind:value={secret} minlength="32" maxlength="4096" autocomplete="new-password" disabled={clearSecret||!vaultReady}/></label><small>{t('Kredensial yang tersimpan tidak ditampilkan kembali. Kosongkan untuk mempertahankan kredensial lama.')}</small>{#if hasSecret}<label class="check"><input type="checkbox" bind:checked={clearSecret} onchange={()=>{if(clearSecret){active=false;secret='';}}}/>{t('Hapus kredensial tersimpan')}</label>{/if}<label class="check"><input type="checkbox" bind:checked={active} disabled={clearSecret||!vaultReady}/>{t('Aktifkan provider ini')}</label><p class="muted">{t('Aktivasi mengganti provider sebelumnya untuk jenis layanan ini dan membatalkan tantangan yang belum selesai.')}</p><div class="form-footer"><div class="actions form-actions"><button type="button" class="quiet" disabled={busy} onclick={()=>{editing=false;secret='';}}>{t('Batal')}</button><button disabled={busy||Boolean(secret&&!vaultReady)}>{t('Simpan')}</button></div></div></form>{/if}
	<section class="providers" aria-busy={loading}>{#if loading}<p role="status">{t('Memuat…')}</p>{:else if !providers.length}<div class="panel"><h2>{t('Belum ada provider yang dikelola panel')}</h2><p class="muted">{t('Tambahkan layanan yang mendukung protokol integrasi. Setiap vendor baru memerlukan adapter yang kompatibel.')}</p></div>{/if}{#each providers as provider(provider.id)}<article class="panel"><div class="heading"><div><small>{label(provider.purpose)}</small><h2>{provider.name}</h2></div><span class="badge">{t(provider.active?'Aktif':'Nonaktif')}</span></div><p class="endpoint">{provider.endpoint}</p><div class="footer"><small>{t(provider.has_secret?'Kredensial tersimpan':'Belum ada kredensial')} · v{provider.version}</small><button class="quiet" onclick={()=>edit(provider)}><Icon name="edit" size={15}/>{t('Edit')}</button></div></article>{/each}</section>
</main>
<style>.integrations{display:grid;gap:12px;align-content:start}.panel{padding:16px;border-radius:var(--radius);min-width:0}.providers{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px}.editor{display:grid;gap:10px;max-width:640px}h2{font-size:15px;margin:4px 0 8px}.heading,.footer,.actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.endpoint{font-size:12px;overflow-wrap:anywhere}.muted,small{font-size:11px;color:var(--muted)}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.providers>.panel{display:flex;flex-direction:column}.providers .footer{margin-top:auto;padding-top:12px}</style>
